/* ============================== interactions ============================== */
function toast(msg,color){
  const box=$('toasts');
  while(box.children.length>=3)box.removeChild(box.firstChild);
  const t=document.createElement('div');t.className='toast';
  t.style.borderLeftColor=color||'var(--cyan)';
  const dot=document.createElement('span');dot.className='dot';dot.style.background=color||'var(--cyan)';
  t.appendChild(dot);t.appendChild(document.createTextNode(msg));box.appendChild(t);
  setTimeout(()=>{t.classList.add('out');setTimeout(()=>t.remove(),320);},2600);
}
function ringBell(){
  if(ringT<.12)return;
