/* exports — capture the SVG in its current pose */
function svgString(){
  const c=svg.cloneNode(true);
  c.setAttribute('xmlns',NS); c.setAttribute('width',1200); c.setAttribute('height',675);
  c.removeAttribute('style'); c.removeAttribute('id');
  return '<?xml version="1.0" encoding="UTF-8"?>\n'+new XMLSerializer().serializeToString(c);
}
function download(blob,name){
  const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;
  document.body.appendChild(a);a.click();a.remove();
  setTimeout(()=>URL.revokeObjectURL(a.href),4000);
}
function exportSVG(){
  try{download(new Blob([svgString()],{type:'image/svg+xml'}),'pelican-velo.svg');
