function exportPNG(){
  try{
    const img=new Image();
    img.onload=function(){
      try{const cv=document.createElement('canvas');cv.width=2400;cv.height=1350;
        const cx=cv.getContext('2d');cx.drawImage(img,0,0,2400,1350);
