/* ============================== controls binding ============================== */
function fillPct(input){const p=(input.value-input.min)/(input.max-input.min)*100;
  input.style.setProperty('--p',p+'%');}
const ranges=[
  ['rpm',v=>{S.rpm=+v;},v=>v+' rpm'],
  ['wheel',v=>{S.wheelR=+v;rebuild();},v=>Math.round(v*0.42)+'″ wheel'],
  ['bounce',v=>{S.bounce=+v;},v=>(+v).toFixed(1)+' px'],
  ['scarf',v=>{S.scarf=+v;},v=>v+' segments'],
  ['hour',v=>{S.hour=+v;applyTime();},()=>''],
  ['wind',v=>{S.wind=+v;},v=>v+' %'],
  ['zoom',v=>{S.zoom=+v;},v=>v+' %']];
ranges.forEach(r=>{
  const input=$(r[0]);
  input.addEventListener('input',()=>{r[1](input.value);fillPct(input);
    const out=r[2](input.value); if(out)$(r[0]+'Val').textContent=out;});
});
function refreshControls(){
  $('rpm').value=S.rpm; $('rpmVal').textContent=S.rpm+' rpm';
  $('wheel').value=S.wheelR; $('wheelVal').textContent=Math.round(S.wheelR*0.42)+'″ wheel';
  $('bounce').value=S.bounce; $('bounceVal').textContent=S.bounce.toFixed(1)+' px';
  $('scarf').value=S.scarf; $('scarfVal').textContent=S.scarf+' segments';
  $('hour').value=S.hour;
