/* ============================== main loop ============================== */
let lastChainStep=0;
function frame(now){
  requestAnimationFrame(frame);
  if(!last)last=now;
  const dt=Math.min(.05,(now-last)/1000); last=now;
  tAmb+=dt*ambScale;
  /* eased cadence */
  rpmCur+=(S.rpm-rpmCur)*Math.min(1,dt*3);
  const effRpm=S.paused?0:rpmCur;
  const wc=effRpm/60*TAU;                    // crank rad/s
  const gear=D.ringR/D.cogR, ww=wc*gear;     // wheel rad/s
  const vpx=ww*D.R, vms=vpx*PXM, kmh=vms*3.6;
  if(!S.paused){
    theta+=wc*dt; dist+=vms*dt;
    wheelDeg+=ww*dt*DEG; chainOff-=wc*D.ringR*dt;
    const step=Math.floor(theta/Math.PI);
    if(step!==lastChainStep){lastChainStep=step;if(effRpm>4)tickChain(.02+effRpm*.0005);}
  }
  const scroll=dist/PXM;
  /* camera */
  const z=S.zoom/100;
  world.setAttribute('transform','translate(600,430) scale('+z+') translate(-600,-430)');
  /* parallax layers */
  const wrap=(g,f)=>g.setAttribute('transform','translate('+f2(-(scroll*f%1200))+',0)');
  wrap(duneG,.3); wrap(palmG,.62); wrap(railG,1); wrap(plankG,1); wrap(fgG,1.25);
  waveOff+=(14+S.wind*.35)*dt*ambScale;
  R.waves.forEach((w,i)=>w.el.setAttribute('transform','translate('+f2(-(waveOff*w.rate%120))+','+
    f2(Math.sin(tAmb*.7+i)*1.5)+')'));
  clouds.forEach(c=>{
    const x=((c.x0-tAmb*(4+S.wind*.14)-scroll*.05)%1600+1600)%1600-200;
    c.g.setAttribute('transform','translate('+f2(x)+','+f2(c.y+Math.sin(tAmb*.3+c.ph)*4)+') scale('+c.s+')');});
  gulls.forEach(g=>{
    const x=((g.base-tAmb*g.sp-scroll*.02)%1500+1500)%1500-150;
    const fl=4+Math.sin(tAmb*7+g.ph)*6;
    g.path.setAttribute('d','M-14 0 Q-7 '+f2(-fl)+' 0 0 Q7 '+f2(-fl)+' 14 0');
    g.g.setAttribute('transform','translate('+f2(x)+','+f2(g.y+Math.sin(tAmb*.9+g.ph)*7)+') scale('+g.sc+')');});
  boatX-= (8+S.wind*.06)*dt*ambScale; if(boatX<-160)boatX=1360;
  R.boatG.setAttribute('transform','translate('+f2(boatX)+','+f2(492+Math.sin(tAmb*.8)*3)+
    ') rotate('+f2(Math.sin(tAmb*.8+.5)*2.5)+')');
  R.boatLamp.setAttribute('opacity',f2(night*.9));
  palms.forEach(p=>p.fr.setAttribute('transform','translate('+p.x+','+p.y+') rotate('+
    f2(Math.sin(tAmb*.9+p.ph)*(2+S.wind*.05))+')'));
  glitter.forEach((g,i)=>g.el.setAttribute('opacity',
    f2(R.glitBase*(0.4+0.6*Math.abs(Math.sin(tAmb*2.4+g.ph))))));
  /* stars & shooting star */
  if(night>0.02){stars.forEach(s=>s.el.setAttribute('opacity',
    f2(clamp(night*1.6*(0.5+0.5*Math.sin(tAmb*s.sp+s.ph)),0,1))));
    if(tAmb>shootAt&&night>.5){shootP=0;shootAt=tAmb+12+Math.random()*14;
      shootX=200+Math.random()*800;shootY=30+Math.random()*130;}
  }
  if(shootP<1){shootP+=dt/.7;const p=clamp(shootP,0,1);
    const x=shootX-260*p,y=shootY+90*p;
    R.shoot.setAttribute('x1',f2(x));R.shoot.setAttribute('y1',f2(y));
    R.shoot.setAttribute('x2',f2(x+46));R.shoot.setAttribute('y2',f2(y-16));
    R.shoot.setAttribute('opacity',f2(Math.sin(p*Math.PI)*night));}
  else R.shoot.setAttribute('opacity',0);
  /* night emissives */
  const flick=.9+.1*Math.sin(tAmb*17);
  R.beam.setAttribute('opacity',f2(night*.5*flick));
  R.bulbHalo.setAttribute('opacity',f2(night*.9*flick));
  R.bulb.setAttribute('opacity',f2(night));
  R.reflector.setAttribute('opacity',f2(night*(.4+.6*Math.abs(Math.sin(tAmb*4)))));
  /* ---- rig kinematics ---- */
  bobY=Math.sin(theta*2)*S.bounce*.6;
  pitch=-2+Math.sin(theta*2+.7)*1.4*(S.bounce/5);
  R.bodyG.setAttribute('transform','translate('+f2(D.H.x)+','+f2(D.H.y+bobY)+') rotate('+f2(pitch)+')');
  R.shadow.setAttribute('rx',f2(150+bobY*.8));
  R.shadow.setAttribute('opacity',f2(.16+bobY*.004));
  R.wheelRear.spin.setAttribute('transform','rotate('+f2(wheelDeg%360)+')');
  R.wheelFront.spin.setAttribute('transform','rotate('+f2(wheelDeg%360)+')');
  R.ring.setAttribute('transform','translate('+D.BB.x+','+D.BB.y+') rotate('+f2(theta*DEG%360)+')');
  R.chain.setAttribute('stroke-dashoffset',f2(chainOff%12));
  const pn={x:D.BB.x+Math.cos(theta)*D.crankR,y:D.BB.y+Math.sin(theta)*D.crankR};
  const pf={x:D.BB.x+Math.cos(theta+Math.PI)*D.crankR,y:D.BB.y+Math.sin(theta+Math.PI)*D.crankR};
  setLine(R.nearCrank,D.BB,pn); setLine(R.farCrank,D.BB,pf);
  R.nearPedal.setAttribute('transform','translate('+f2(pn.x)+','+f2(pn.y)+')');
  R.farPedal.setAttribute('transform','translate('+f2(pf.x)+','+f2(pf.y)+')');
  const hn=bodyToWorld(6,-4), hf=bodyToWorld(-6,-6);
  const kn=solveIK(hn,pn), kf=solveIK(hf,pf);
  setLine(R.nearLeg.thigh,hn,kn); setLine(R.nearLeg.shin,kn,pn);
  setLine(R.farLeg.thigh,hf,kf); setLine(R.farLeg.shin,kf,pf);
  const ankN=-8+Math.sin(theta+.6)*10, ankF=-8+Math.sin(theta+Math.PI+.6)*10;
  R.nearLeg.foot.setAttribute('transform','translate('+f2(pn.x)+','+f2(pn.y-3)+') rotate('+f2(ankN)+')');
  R.farLeg.foot.setAttribute('transform','translate('+f2(pf.x)+','+f2(pf.y-3)+') rotate('+f2(ankF)+')');
  /* wings */
  const sh=bodyToWorld(44,-62), shf=bodyToWorld(26,-46);
  const flex=Math.sin(theta*2)*2;
  R.nearWing.setAttribute('d','M'+f2(sh.x)+' '+f2(sh.y)+' C'+f2(sh.x+26)+' '+f2(sh.y+16+flex)+
    ' '+f2(D.G.x-30)+' '+f2(D.G.y-34)+' '+f2(D.G.x)+' '+f2(D.G.y));
  R.nearWingShade.setAttribute('d','M'+f2(sh.x+4)+' '+f2(sh.y+7)+' C'+f2(sh.x+26)+' '+f2(sh.y+20+flex)+
    ' '+f2(D.G.x-28)+' '+f2(D.G.y-26)+' '+f2(D.G.x-4)+' '+f2(D.G.y+3));
  R.farWing.setAttribute('d','M'+f2(shf.x)+' '+f2(shf.y)+' Q'+f2(shf.x+34)+' '+f2(shf.y+34)+
    ' '+f2(D.G.x-4)+' '+f2(D.G.y+10));
  R.farWingTip.setAttribute('d','M'+f2(D.G.x-16)+' '+f2(D.G.y+6)+' q8 8 16 5');
  R.fingers.forEach((fp,i)=>{const ox=i*5-4;
    fp.setAttribute('d','M'+f2(D.G.x+ox-4)+' '+f2(D.G.y-4+i)+' q5 9 11 4');});
  /* head life */
  tiltImp*=Math.exp(-6*dt);
  const headTilt=tiltImp+Math.sin(theta*2+1)*1.5;
  R.headG.setAttribute('transform','rotate('+f2(headTilt)+' 118 -150)');
  R.tailG.setAttribute('transform','rotate('+f2(Math.sin(tAmb*3)*4)+' -66 -34)');
  /* blink */
  if(tAmb>blinkAt){blinkP=0;blinkAt=tAmb+2.5+Math.random()*3.5;}
  if(blinkP<1){blinkP+=dt/.18;
    const s=1-Math.sin(clamp(blinkP,0,1)*Math.PI)*.92;
    R.eyeG.setAttribute('transform','translate(127,-157) scale(1,'+f2(s)+') translate(-127,157)');}
  else R.eyeG.setAttribute('transform','');
  /* honk / pouch */
  let open=0;
  if(honkT<1){honkT+=dt/.55;const p=clamp(honkT,0,1);
    open=p<.15?p/.15:1-(p-.15)/.85;}
  const sag=Math.sin(theta*2+2)*3*(S.bounce/5+.3)+open*30;
  R.pouch.setAttribute('d','M129 -148 Q196 '+f2(-104+sag)+' 256 -142 Q261 -142 260 -146 L129 -153 Z');
  R.pouchG.setAttribute('transform','rotate('+f2(open*14)+' 129 -148)');
  R.upperBeakG.setAttribute('transform','rotate('+f2(-open*10)+' 126 -152)');
  R.fishPoke.setAttribute('opacity',fishT<1?0:1);
  /* scarf ribbon */
  const root=bodyToWorld(84,-116);
  const Nseg=Math.round(S.scarf), segLen=13;
  const amp=3+S.wind*.10+effRpm*.04, freq=3+effRpm*.05+S.wind*.06;
  const droop=Math.max(6,26*(1-S.wind*.008)), lift=S.wind*.35;
  function ribbon(n,phase,width){
    let d='M'+f2(root.x)+' '+f2(root.y),lx=root.x,ly=root.y;
