    R.comicBell.setAttribute('x',f2(D.bell.x-6));
    R.comicBell.setAttribute('y',f2(D.bell.y-44-30*p));
    R.comicBell.setAttribute('opacity',f2(p<.7?1:1-(p-.7)/.3));
    R.comicBell.setAttribute('transform','rotate(-8 '+f2(D.bell.x-6)+' '+f2(D.bell.y-60)+
      ') translate('+f2(D.bell.x-6)+' '+f2(D.bell.y-60)+') scale('+f2(pop)+') translate('+f2(-(D.bell.x-6))+' '+f2(-(D.bell.y-60))+')');
  } else {R.bellArcs.setAttribute('opacity',0);R.bellDome.setAttribute('transform','');
    R.comicBell.setAttribute('opacity',0);}
  /* honk comic */
  if(honkT<1){const p=clamp(honkT,0,1),pop=p<.2?(p/.2)*1.1:1.1-.1*Math.min(1,(p-.2)/.3);
    R.comicHonk.setAttribute('opacity',f2(p<.65?1:1-(p-.65)/.35));
    const hx=+R.comicHonk.getAttribute('x'),hy=+R.comicHonk.getAttribute('y');
    R.comicHonk.setAttribute('transform','rotate(6 '+hx+' '+hy+') translate('+hx+' '+f2(hy-20*p)+
