  else R.comicHonk.setAttribute('opacity',0);
  /* fish jump */
  if(fishT<1){fishT+=dt/1.0;const p=clamp(fishT,0,1);
    const fx=fishStart.x+Math.sin(p*Math.PI)*60, fy=fishStart.y-160*Math.sin(p*Math.PI);
    R.fishJumpG.setAttribute('opacity',f2(p<.9?1:1-(p-.9)/.1));
    R.fishJumpG.setAttribute('transform','translate('+f2(fx)+','+f2(fy)+') rotate('+f2(p*300-20)+')');
