      s.setAttribute('cx',f2(fishStart.x+30+i*16));s.setAttribute('cy',f2(fishStart.y-140+i*10));
      s.setAttribute('opacity',f2(Math.sin(sp*Math.PI)*.9));});}
  else {R.fishJumpG.setAttribute('opacity',0);R.sparkles.forEach(s=>s.setAttribute('opacity',0));}
  /* speed lines & dust */
  const slOp=S.spray?clamp((kmh-20)/40,0,1)*.35:0;
  speedRects.forEach(s=>{
    s.el.setAttribute('x',f2(1250-((scroll*2.2+s.off)%1500)));
    s.el.setAttribute('width',f2(40+kmh*3));
    s.el.setAttribute('opacity',f2(slOp));});
  if(S.spray&&!S.paused&&effRpm>15){
    spawnAcc+=dt*(effRpm/12);
    while(spawnAcc>1){spawnAcc-=1;
      const d=dust.find(q=>!q.on); if(!d)break;
      d.on=true;d.age=0;d.life=.5+Math.random()*.4;
      d.x=D.A.x-6;d.y=GY-2;d.r=2+Math.random()*3;
      d.vx=-(60+vpx*.3)+(Math.random()-.5)*30;d.vy=-20-Math.random()*45;
      d.el.setAttribute('display','inline');d.el.setAttribute('r',f2(d.r));}
  }
  dust.forEach(d=>{if(!d.on)return;d.age+=dt;
    if(d.age>=d.life){d.on=false;d.el.setAttribute('display','none');return;}
    d.x+=d.vx*dt;d.y+=d.vy*dt;d.vy+=140*dt;
    d.el.setAttribute('cx',f2(d.x));d.el.setAttribute('cy',f2(d.y));
    d.el.setAttribute('opacity',f2(.7*(1-d.age/d.life)));});
  /* guides */
  if(S.guides){
    setLine(R.gBones[0],hn,kn);setLine(R.gBones[1],kn,pn);
    setLine(R.gBones[2],hf,kf);setLine(R.gBones[3],kf,pf);
    [hn,kn,pn,hf,kf,pf].forEach((j,i)=>{R.gJoints[i].setAttribute('cx',f2(j.x));
      R.gJoints[i].setAttribute('cy',f2(j.y));});
    R.gTheta.textContent='θ '+Math.round((theta*DEG)%360)+'°';
    R.gCad.textContent='cadence '+Math.round(effRpm)+' rpm';
  }
  /* HUD */
  hudT+=dt;
  if(hudT>.2){hudT=0;
    $('hudSpeed').textContent=kmh.toFixed(1);
    $('hudCad').textContent=Math.round(effRpm);
    $('hudTrip').textContent=dist<1000?Math.round(dist)+' m':(dist/1000).toFixed(2)+' km';}
}

/* ============================== boot ============================== */
rebuild(); applyPaint(); applyTime(); refreshControls();
setSound(true); setPaused(false);
if(reduced){setPaused(true);toast('Reduced motion detected — press Space when ready','var(--amber)');}
setTimeout(()=>$('bellHint').classList.add('hide'),20000);
requestAnimationFrame(frame);
})();
</script>
</body>
