<script>
(function(){
'use strict';
/* ============================== helpers ============================== */
const NS='http://www.w3.org/2000/svg';
const $=id=>document.getElementById(id);
function el(tag,attrs,parent){const n=document.createElementNS(NS,tag);
  for(const k in attrs){if(k==='text')n.textContent=attrs[k];else n.setAttribute(k,attrs[k]);}
  if(parent)parent.appendChild(n);return n;}
const clamp=(v,a,b)=>v<a?a:v>b?b:v;
const lerp=(a,b,t)=>a+(b-a)*t;
const TAU=Math.PI*2, DEG=180/Math.PI;
function hexRGB(h){return [parseInt(h.slice(1,3),16),parseInt(h.slice(3,5),16),parseInt(h.slice(5,7),16)];}
function mixHex(a,b,t){const A=hexRGB(a),B=hexRGB(b);
  return '#'+A.map((v,i)=>Math.round(lerp(v,B[i],t)).toString(16).padStart(2,'0')).join('');}
const f2=n=>(+n).toFixed(2);
const DISP='"Avenir Next","Trebuchet MS","Segoe UI",sans-serif';
const MONO='ui-monospace,Menlo,Consolas,monospace';

/* ============================== state ============================== */
const DEFAULTS={rpm:72,wheelR:62,bounce:5,scarf:10,hour:16.5,wind:22,zoom:100,
  frame:'#2e7cff',kit:'#ff5d4d',guides:false,spray:true};
const S=Object.assign({},DEFAULTS);
S.paused=false; S.sound=true;
const PXM=0.009;                 // metres per scene pixel
const GY=560, BX=560;            // ground line, bike anchor x
let dist=0, theta=0.6, wheelDeg=0, chainOff=0, rpmCur=0;
let tAmb=0, last=0, hudT=0, spawnAcc=0, waveOff=0;
let ringT=9, honkT=9, fishT=9, tiltImp=0, lastHonk=-9;
let blinkAt=2.5, blinkP=9, shootAt=16, shootP=9, shootX=0, shootY=0;
let night=0, sunX=600, sunY=120, moonX=200, moonY=120, sunUp=1;
let fishStart={x:0,y:0};
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const ambScale=reduced?0.35:1;

/* ============================== scene refs ============================== */
const svg=$('scene'); const R={}; const D={};
const paintFrame=[], paintFrameDark=[], paintKit=[], paintKitDark=[];
const clouds=[], gulls=[], palms=[], stars=[], glitter=[], dust=[], speedRects=[];
let L1=80, L2=72;

/* ---------- defs ---------- */
const defs=el('defs',{},svg);
function grad(id,stops,attrs){const g=el('linearGradient',Object.assign({id},attrs||{}),defs);
  return stops.map(s=>el('stop',{offset:s[0],'stop-color':s[1],'stop-opacity':s[2]==null?1:s[2]},g));}
function radial(id,stops){const g=el('radialGradient',{id},defs);
  return stops.map(s=>el('stop',{offset:s[0],'stop-color':s[1],'stop-opacity':s[2]==null?1:s[2]},g));}
const skyStops=grad('skyGrad',[[0,'#2b80d0'],[.55,'#7cc4ee'],[1,'#ffe6b0']],{x1:0,y1:0,x2:0,y2:1});
const seaStops=grad('seaGrad',[[0,'#0e9cb8'],[1,'#0a7396']],{x1:0,y1:0,x2:0,y2:1});
radial('sunGlow',[[0,'#fff3c9',.9],[.4,'#ffd98a',.45],[1,'#ffd98a',0]]);
radial('moonGlow',[[0,'#dff2ff',.7],[1,'#dff2ff',0]]);
grad('beakGrad',[[0,'#ffc25e'],[1,'#ff9a3d']],{x1:0,y1:0,x2:0,y2:1});
grad('pouchGrad',[[0,'#ffb054'],[1,'#f07a2e']],{x1:0,y1:0,x2:0,y2:1});
grad('bellGrad',[[0,'#ffd76e'],[1,'#e89b1c']],{x1:0,y1:0,x2:0,y2:1});
grad('beamGrad',[[0,'#ffe9a8',.55],[1,'#ffe9a8',0]],{x1:0,y1:0,x2:1,y2:0});
radial('bulbGlow',[[0,'#ffe9a8',.9],[1,'#ffe9a8',0]]);

/* ---------- world root (camera zoom applies here) ---------- */
const world=el('g',{id:'world'},svg);

/* sky */
el('rect',{x:-1300,y:-520,width:3800,height:1720,fill:'url(#skyGrad)'},world);

/* stars */
R.starG=el('g',{opacity:0},world);
for(let i=0;i<64;i++){
  const s=el('circle',{cx:f2(-600+Math.random()*2400),cy:f2(-320+Math.random()*620),
    r:f2(.7+Math.random()*1.2),fill:'#eef9ff'},R.starG);
  stars.push({el:s,ph:Math.random()*TAU,sp:1.2+Math.random()*2});
}
R.shoot=el('line',{x1:0,y1:0,x2:0,y2:0,stroke:'#eef9ff','stroke-width':2.5,
  'stroke-linecap':'round',opacity:0},world);

/* sun */
R.sunG=el('g',{},world);
R.sunHalo=el('circle',{r:120,fill:'url(#sunGlow)'},R.sunG);
R.sunDisc=el('circle',{r:44,fill:'#fff4d6'},R.sunG);

/* clouds */
const cloudG=el('g',{},world);
function makeCloud(x,y,s){
  const g=el('g',{},cloudG); const puffs=[];
  [[0,0,46,26],[36,-12,34,20],[-38,-6,32,18],[12,10,40,18]].forEach(p=>{
    puffs.push(el('ellipse',{cx:p[0],cy:p[1],rx:p[2],ry:p[3],fill:'#fff3da'},g));});
  clouds.push({g,puffs,x0:x,y,s,ph:Math.random()*TAU});
}
makeCloud(220,96,1.25); makeCloud(700,150,.85); makeCloud(1050,64,1.5);

/* gulls */
const gullG=el('g',{},world);
[[130,27,1,0],[188,35,.78,2.1],[96,20,.6,4.2]].forEach(p=>{
  const g=el('g',{},gullG);
  const path=el('path',{d:'M-14 0 Q-7 -8 0 0 Q7 -8 14 0',fill:'none',
    stroke:'#3a4a5c','stroke-width':3.4,'stroke-linecap':'round'},g);
  gulls.push({g,path,y:p[0],sp:p[1],sc:p[2],ph:p[3],base:Math.random()*1400});
});

/* sea */
el('rect',{x:-1300,y:470,width:3800,height:92,fill:'url(#seaGrad)'},world);
R.horizon=el('rect',{x:-1300,y:469,width:3800,height:2,fill:'#ffe6b0',opacity:.65},world);

/* wave ribbons (periodic, transform-scrolled) */
function wavePath(base,amp){let d='M-1320 '+(base+amp);
  for(let x=-1320;x<=2520;x+=24){d+=' L'+x+' '+f2(base+Math.sin(x/120*TAU)*amp);}
  return d+' L2520 562 L-1320 562 Z';}
R.waves=[];
[[481,5,.14,.32,1],[506,7,.24,.22,1.6],[534,9,.36,.14,2.3]].forEach(w=>{
  const p=el('path',{d:wavePath(w[0],w[1]),fill:'#3fb9cf','fill-opacity':.85,
    stroke:'#eef9ff','stroke-opacity':w[3],'stroke-width':2},world);
  R.waves.push({el:p,rate:w[4],mix:w[2],base:w[0]});
  if(w[4]===1.6){ /* boat sits between wave bands */ }
});
/* boat inserted between band 1 and 2 for depth */
R.boatG=el('g',{},world);
world.insertBefore(R.boatG,R.waves[1].el);
el('path',{d:'M-34 0 L34 0 L22 12 L-26 12 Z',fill:'#d95f43'},R.boatG);
el('rect',{x:-30,y:2,width:60,height:3,fill:'#eef9ff',opacity:.8},R.boatG);
el('line',{x1:2,y1:0,x2:2,y2:-46,stroke:'#5a4632','stroke-width':3},R.boatG);
el('path',{d:'M4 -44 L4 -4 L30 -6 Z',fill:'#eef9ff'},R.boatG);
el('path',{d:'M0 -40 L0 -4 L-20 -6 Z',fill:'#ffb02e'},R.boatG);
R.boatLamp=el('circle',{cx:2,cy:-48,r:3,fill:'#ffd76e',opacity:0},R.boatG);
let boatX=980;

/* sun glitter on water */
R.glitG=el('g',{},world);
for(let i=0;i<12;i++){
  const g=el('rect',{x:0,y:482+i*5.6,width:8+Math.random()*18,height:2.2,rx:1.1,
    fill:'#ffd98a',opacity:0},R.glitG);
  glitter.push({el:g,dx:(Math.random()-.5)*70,ph:Math.random()*TAU});
}

/* ---------- parallax tile layers ---------- */
function tiles(builder){const g=el('g',{},world);
  for(let i=-1;i<=1;i++){const t=el('g',{transform:'translate('+(i*1200)+',0)'},g);builder(t,i);}
  return g;}
const duneG=tiles(t=>{
  el('path',{d:'M0 560 L0 536 Q90 508 180 534 Q260 552 340 540 Q430 512 520 538 Q610 556 700 542 Q800 514 900 538 Q1000 554 1090 540 Q1150 530 1200 538 L1200 560 Z',
    fill:'#e8cf9a'},t);
  [[120,528],[420,522],[760,524],[1060,532]].forEach(p=>{
    el('path',{d:'M'+p[0]+' '+p[1]+' q-4 -14 -9 -18 M'+p[0]+' '+p[1]+' q1 -16 5 -20 M'+p[0]+' '+p[1]+' q6 -10 12 -13',
      stroke:'#4aa860','stroke-width':2.5,fill:'none','stroke-linecap':'round'},t);});
  el('line',{x1:950,y1:538,x2:950,y2:508,stroke:'#8a5a3a','stroke-width':3},t);
  el('path',{d:'M922 514 Q950 490 978 514 Z',fill:'#ff5d4d'},t);
  el('path',{d:'M936 505 Q950 494 964 505 L958 512 Q950 505 942 512 Z',fill:'#eef9ff'},t);
});
const palmG=tiles((t,ti)=>{
  [[180,150],[820,118]].forEach(p=>{
    const x=p[0],h=p[1],topX=x+16,topY=588-h;
    el('path',{d:'M'+x+' 588 Q'+(x+5)+' '+(588-h*.6)+' '+topX+' '+topY,
      stroke:'#8a5a3a','stroke-width':10,fill:'none','stroke-linecap':'round'},t);
    const fr=el('g',{},t);
    [[-46,-6],[-34,-24],[-10,-32],[16,-30],[38,-16],[46,2]].forEach(v=>{
      el('path',{d:'M0 0 Q'+(v[0]*.55)+' '+(v[1]-14)+' '+v[0]+' '+v[1],
        stroke:'#2f9e5f','stroke-width':7,fill:'none','stroke-linecap':'round'},fr);});
    el('circle',{cx:-4,cy:4,r:4.5,fill:'#6b4226'},fr);
    el('circle',{cx:5,cy:6,r:4.5,fill:'#6b4226'},fr);
    palms.push({fr,x:topX+ti*1200,y:topY,ph:(x+ti*1200)*.013});
  });
});
R.sand=el('rect',{x:-1300,y:648,width:3800,height:120,fill:'#f6dfa6'},world);
const railG=tiles(t=>{
  for(let x=60;x<1200;x+=120)el('rect',{x:x-4,y:524,width:8,height:38,fill:'#c9955c'},t);
  el('rect',{x:0,y:518,width:1200,height:9,rx:4,fill:'#d9a86b'},t);
  el('rect',{x:0,y:518,width:1200,height:3,rx:1.5,fill:'#f2dfb6',opacity:.6},t);
  el('rect',{x:0,y:543,width:1200,height:5,fill:'#c9955c'},t);
});
const plankG=tiles(t=>{
  el('rect',{x:0,y:560,width:1200,height:54,fill:'#d9a86b'},t);
  el('rect',{x:0,y:560,width:1200,height:3,fill:'#f2dfb6',opacity:.55},t);
  for(let x=0;x<=1200;x+=40)el('line',{x1:x,y1:561,x2:x,y2:614,stroke:'#b9854d','stroke-width':3},t);
  for(let x=20;x<1200;x+=80){el('circle',{cx:x,cy:575,r:1.6,fill:'#8a5a34'},t);
    el('circle',{cx:x,cy:600,r:1.6,fill:'#8a5a34'},t);}
  el('rect',{x:0,y:614,width:1200,height:13,fill:'#b07a44'},t);
  for(let x=0;x<1200;x+=120)el('rect',{x:x+2,y:614,width:13,height:56,fill:'#8a5a34'},t);
});
/* speed lines behind the rig */
R.speedG=el('g',{},world);
for(let i=0;i<6;i++){
  const r=el('rect',{x:0,y:376+i*30+Math.random()*14,width:60,height:3,rx:1.5,
    fill:'#eef9ff',opacity:0},R.speedG);
  speedRects.push({el:r,off:i*233+Math.random()*80});
}

/* ============================== the rig ============================== */
const rig=el('g',{},world);
R.shadow=el('ellipse',{cx:BX,cy:GY+3,rx:150,ry:9,fill:'#06141d',opacity:.16},rig);

function makeWheel(){
  const g=el('g',{},rig);
  el('circle',{r:0,class:'tire',fill:'none',stroke:'#1d2733','stroke-width':12},g);
  el('circle',{r:0,class:'rim',fill:'none',stroke:'#cfd8e3','stroke-width':4},g);
  const acc=el('circle',{r:0,fill:'none','stroke-width':2,opacity:.85},g); paintFrame.push(acc);
  const spin=el('g',{},g);
  const spokes=[];
  for(let i=0;i<10;i++)spokes.push(el('line',{x1:0,y1:0,x2:0,y2:0,stroke:'#b9c4cf','stroke-width':2.4},spin));
  const valve=el('circle',{r:3,fill:'#ffb02e'},spin);
  el('circle',{r:6.5,fill:'#1d2733'},g); el('circle',{r:2.6,fill:'#eef9ff'},g);
  return {g,spin,spokes,valve,tire:g.children[0],rim:g.children[1],acc};
}
R.wheelRear=makeWheel(); R.wheelFront=makeWheel();

/* far crank + pedal + leg (behind frame) */
R.farCrank=el('line',{stroke:'#16202b','stroke-width':8,'stroke-linecap':'round',opacity:.85},rig);
R.farPedal=el('g',{opacity:.85},rig);
el('rect',{x:-14,y:-4,width:28,height:8,rx:3,fill:'#101820'},R.farPedal);
el('rect',{x:10,y:-2,width:4,height:4,fill:'#ffb02e'},R.farPedal);
R.farLeg={thigh:el('line',{stroke:'#e3d2b4','stroke-width':17,'stroke-linecap':'round'},rig),
  shin:el('line',{stroke:'#e08a3a','stroke-width':8,'stroke-linecap':'round'},rig),
  foot:el('g',{},rig)};
el('path',{d:'M-4 -3 L20 -5 L26 2 L16 3 L20 6 L8 5 L12 8 L-2 5 Z',fill:'#e08a3a',
  stroke:'#c67424','stroke-width':1},R.farLeg.foot);

/* rear rack + fish crate */
R.rackG=el('g',{},rig);
el('line',{x1:-34,y1:0,x2:30,y2:0,stroke:'#22303e','stroke-width':5,'stroke-linecap':'round'},R.rackG);
el('line',{x1:-30,y1:0,x2:-6,y2:38,stroke:'#22303e','stroke-width':4},R.rackG);
el('line',{x1:26,y1:0,x2:6,y2:38,stroke:'#22303e','stroke-width':4},R.rackG);
el('rect',{x:-26,y:-27,width:52,height:27,rx:3,fill:'#c98a4b',stroke:'#8a5a34','stroke-width':2},R.rackG);
el('line',{x1:-26,y1:-14,x2:26,y2:-14,stroke:'#8a5a34','stroke-width':1.5},R.rackG);
const strap=el('rect',{x:-4,y:-27,width:8,height:27,fill:'#ff5d4d'},R.rackG); paintKit.push(strap);
el('path',{d:'M12 -27 L6 -40 L14 -35 L20 -42 L20 -28 Z',fill:'#2ec4b6',stroke:'#1b2430','stroke-width':1},R.rackG);

/* frame */
R.frame=el('path',{fill:'none','stroke-width':9,'stroke-linecap':'round','stroke-linejoin':'round'},rig);
paintFrame.push(R.frame);
R.fork=el('path',{fill:'none','stroke-width':7,'stroke-linecap':'round'},rig); paintFrame.push(R.fork);
R.fenderR=el('path',{fill:'none','stroke-width':6,'stroke-linecap':'round',opacity:.95},rig); paintFrameDark.push(R.fenderR);
R.fenderF=el('path',{fill:'none','stroke-width':6,'stroke-linecap':'round',opacity:.95},rig); paintFrameDark.push(R.fenderF);
R.chain=el('path',{fill:'none',stroke:'#39465a','stroke-width':5,'stroke-dasharray':'7 5'},rig);
R.ring=el('g',{},rig);
el('circle',{r:17,class:'ringOuter',fill:'none',stroke:'#1d2733','stroke-width':6},R.ring);
for(let i=0;i<5;i++)el('line',{x1:0,y1:0,x2:0,y2:0,class:'ringSpoke',stroke:'#1d2733','stroke-width':3},R.ring);
el('circle',{r:4.5,fill:'#1d2733'},R.ring);
R.seatpost=el('line',{stroke:'#9fb0c0','stroke-width':6,'stroke-linecap':'round'},rig);
R.saddle=el('g',{},rig);
el('path',{d:'M-22 0 Q-25 -9 -12 -10 L16 -8 Q24 -7 22 -1 Q0 5 -22 0 Z',fill:'#1c2733'},R.saddle);
el('path',{d:'M-16 -7 Q0 -10 14 -6',stroke:'#3a4a5c','stroke-width':2,fill:'none'},R.saddle);
R.bar=el('path',{fill:'none',stroke:'#22303e','stroke-width':7,'stroke-linecap':'round'},rig);
R.grip=el('line',{stroke:'#101820','stroke-width':11,'stroke-linecap':'round'},rig);
R.gripCap=el('circle',{r:3.2,fill:'#ffb02e'},rig);
R.lamp=el('g',{},rig);
el('rect',{x:-5,y:-7,width:14,height:14,rx:4,fill:'#22303e'},R.lamp);
el('circle',{cx:9,cy:0,r:5,fill:'#ffd76e'},R.lamp);

/* far wing (behind body) */
R.farWing=el('path',{fill:'none',stroke:'#e4d4b6','stroke-width':14,'stroke-linecap':'round'},rig);
R.farWingTip=el('path',{fill:'none',stroke:'#3a4656','stroke-width':5,'stroke-linecap':'round'},rig);

/* ---------- pelican body (local coords, hip at origin) ---------- */
R.bodyG=el('g',{class:'clickable'},rig);
el('title',{text:'点我 —— 嘎！'},R.bodyG);
R.tailG=el('g',{},R.bodyG);
el('path',{d:'M-62 -28 L-96 -40 L-76 -44 L-100 -56 L-74 -54 L-90 -72 L-62 -50 Z',
  fill:'#fbf3e4',stroke:'#d9c8a8','stroke-width':1.5,'stroke-linejoin':'round'},R.tailG);
el('path',{d:'M-72 -26 C-80 -62 -44 -90 2 -90 C46 -90 74 -66 77 -36 C80 -12 52 6 10 8 C-34 10 -66 0 -72 -26 Z',
  fill:'#fbf3e4',stroke:'#d9c8a8','stroke-width':1.5},R.bodyG);
el('path',{d:'M-58 -16 C-40 4 20 8 44 -6 C24 10 -28 12 -58 -16 Z',fill:'#ecdcbc',opacity:.9},R.bodyG);
el('path',{d:'M56 -62 C92 -66 84 -108 106 -130 C112 -137 116 -142 118 -148',
  fill:'none',stroke:'#fbf3e4','stroke-width':26,'stroke-linecap':'round'},R.bodyG);
el('path',{d:'M52 -58 C86 -62 80 -104 102 -126',fill:'none',stroke:'#e8d9bd',
  'stroke-width':7,'stroke-linecap':'round',opacity:.6},R.bodyG);
/* head group (tilts) */
R.headG=el('g',{},R.bodyG);
