/* ============================== geometry rebuild ============================== */
function arcPath(cx,cy,r,a0,a1,large,sweep){
  const p0x=cx+r*Math.cos(a0/DEG),p0y=cy+r*Math.sin(a0/DEG);
  const p1x=cx+r*Math.cos(a1/DEG),p1y=cy+r*Math.sin(a1/DEG);
  return 'M'+f2(p0x)+' '+f2(p0y)+' A'+r+' '+r+' 0 '+large+' '+sweep+' '+f2(p1x)+' '+f2(p1y);}
function rebuild(){
  const Rr=S.wheelR, gy=GY;
  D.R=Rr;
  D.A={x:BX-105,y:gy-Rr}; D.F={x:BX+105,y:gy-Rr};
  D.BB={x:BX-10,y:gy-Rr+10};
  D.crankR=Rr*0.55; D.ringR=D.crankR*0.5; D.cogR=8;
  D.C={x:BX-33,y:gy-Rr-68};
  D.SP={x:BX-39,y:gy-Rr-80};
  D.H={x:D.SP.x+2,y:D.SP.y-10};
  D.HT={x:D.F.x-26,y:gy-Rr-86}; D.HB={x:D.F.x-14,y:gy-Rr-34};
  D.G={x:D.HT.x-12,y:D.HT.y-20};
  D.bell={x:D.HT.x+6,y:D.HT.y-14};
  D.lamp={x:D.HB.x+10,y:D.HB.y-6};
  /* wheels */
  [R.wheelRear,R.wheelFront].forEach((w,i)=>{
    const c=i?D.F:D.A;
    w.g.setAttribute('transform','translate('+c.x+','+c.y+')');
    w.tire.setAttribute('r',Rr-6); w.rim.setAttribute('r',Rr-13); w.acc.setAttribute('r',Rr-16);
    w.spokes.forEach((s,k)=>{const a=k/10*TAU;
      s.setAttribute('x2',f2(Math.cos(a)*(Rr-15)));s.setAttribute('y2',f2(Math.sin(a)*(Rr-15)));});
    w.valve.setAttribute('cx',0); w.valve.setAttribute('cy',-(Rr-19));
  });
  /* frame */
  R.frame.setAttribute('d','M'+D.A.x+' '+D.A.y+' L'+D.BB.x+' '+D.BB.y+
    ' M'+D.BB.x+' '+D.BB.y+' L'+D.C.x+' '+D.C.y+
    ' M'+D.A.x+' '+D.A.y+' L'+D.C.x+' '+D.C.y+
    ' M'+D.C.x+' '+D.C.y+' L'+D.HT.x+' '+D.HT.y+
    ' M'+D.HT.x+' '+D.HT.y+' L'+D.HB.x+' '+D.HB.y+
    ' M'+D.HB.x+' '+D.HB.y+' L'+D.BB.x+' '+D.BB.y);
  R.fork.setAttribute('d','M'+D.HB.x+' '+D.HB.y+' Q'+(D.HB.x+8)+' '+(D.HB.y+22)+' '+D.F.x+' '+D.F.y);
  R.fenderR.setAttribute('d',arcPath(D.A.x,D.A.y,Rr+8,185,-5,1,0));
  R.fenderF.setAttribute('d',arcPath(D.F.x,D.F.y,Rr+8,-160,-20,0,0));
  R.rackG.setAttribute('transform','translate('+(D.A.x-4)+','+(D.A.y-Rr-14)+')');
  /* chain (belt around cog + ring) */
  const dx=D.BB.x-D.A.x, dy=D.BB.y-D.A.y, dd=Math.hypot(dx,dy);
  const phi=Math.atan2(dy,dx), al=Math.acos(clamp((D.ringR-D.cogR)/dd,-1,1));
  const nT={x:Math.cos(phi-al),y:Math.sin(phi-al)}, nB={x:Math.cos(phi+al),y:Math.sin(phi+al)};
  const cT={x:D.A.x+D.cogR*nT.x,y:D.A.y+D.cogR*nT.y}, rT={x:D.BB.x+D.ringR*nT.x,y:D.BB.y+D.ringR*nT.y};
  const cB={x:D.A.x+D.cogR*nB.x,y:D.A.y+D.cogR*nB.y}, rB={x:D.BB.x+D.ringR*nB.x,y:D.BB.y+D.ringR*nB.y};
  R.chain.setAttribute('d','M'+f2(cT.x)+' '+f2(cT.y)+' L'+f2(rT.x)+' '+f2(rT.y)+
    ' A'+f2(D.ringR)+' '+f2(D.ringR)+' 0 1 1 '+f2(rB.x)+' '+f2(rB.y)+
    ' L'+f2(cB.x)+' '+f2(cB.y)+' A'+D.cogR+' '+D.cogR+' 0 0 1 '+f2(cT.x)+' '+f2(cT.y)+' Z');
  R.ring.children[0].setAttribute('r',f2(D.ringR));
  for(let i=0;i<5;i++){const a=i/5*TAU,s=R.ring.children[1+i];
    s.setAttribute('x2',f2(Math.cos(a)*D.ringR));s.setAttribute('y2',f2(Math.sin(a)*D.ringR));}
  /* cockpit */
  R.seatpost.setAttribute('x1',D.C.x);R.seatpost.setAttribute('y1',D.C.y);
  R.seatpost.setAttribute('x2',D.SP.x);R.seatpost.setAttribute('y2',D.SP.y+2);
  R.saddle.setAttribute('transform','translate('+D.SP.x+','+D.SP.y+')');
  const stX=D.HT.x+10, stY=D.HT.y-14;
  R.bar.setAttribute('d','M'+D.HT.x+' '+D.HT.y+' L'+stX+' '+stY+
    ' Q'+(stX+13)+' '+(stY-14)+' '+(stX-1)+' '+(stY-19)+
    ' Q'+(stX-15)+' '+(stY-22)+' '+D.G.x+' '+D.G.y);
  R.grip.setAttribute('x1',D.G.x);R.grip.setAttribute('y1',D.G.y-4);
  R.grip.setAttribute('x2',D.G.x-2);R.grip.setAttribute('y2',D.G.y+8);
  R.gripCap.setAttribute('cx',D.G.x-2);R.gripCap.setAttribute('cy',D.G.y+10);
  R.bellG.setAttribute('transform','translate('+D.bell.x+','+D.bell.y+')');
  R.lamp.setAttribute('transform','translate('+D.lamp.x+','+D.lamp.y+')');
  const lx=D.lamp.x+9, ly=D.lamp.y;
  R.beam.setAttribute('d','M'+lx+' '+ly+' L'+(lx+310)+' '+(ly-72)+' L'+(lx+310)+' '+GY+' Z');
  R.bulbHalo.setAttribute('cx',lx);R.bulbHalo.setAttribute('cy',ly);
  R.bulb.setAttribute('cx',lx);R.bulb.setAttribute('cy',ly);
  R.reflector.setAttribute('x',D.C.x-6);R.reflector.setAttribute('y',D.C.y+14);
  /* guides statics */
  R.gCrank.setAttribute('cx',D.BB.x);R.gCrank.setAttribute('cy',D.BB.y);R.gCrank.setAttribute('r',f2(D.crankR));
  [[D.A,0],[D.A,1],[D.F,2],[D.F,3]].forEach(p=>{const l=R.gCross[p[1]],c=p[0],h=p[1]%2;
    l.setAttribute('x1',h?c.x:c.x-9);l.setAttribute('y1',h?c.y-9:c.y);
    l.setAttribute('x2',h?c.x:c.x+9);l.setAttribute('y2',h?c.y+9:c.y);});
  R.gTheta.setAttribute('x',D.BB.x+46);R.gTheta.setAttribute('y',D.BB.y-46);
  R.gCad.setAttribute('x',D.BB.x+46);R.gCad.setAttribute('y',D.BB.y-32);
  R.gLen.setAttribute('x',D.H.x-118);R.gLen.setAttribute('y',D.H.y-4);
}

/* ============================== paint & time ============================== */
function applyPaint(){
  const fd=mixHex(S.frame,'#06141d',.3), kd=mixHex(S.kit,'#06141d',.25);
  paintFrame.forEach(e=>e.setAttribute('stroke',S.frame));
  paintFrameDark.forEach(e=>e.setAttribute('stroke',fd));
  paintKit.forEach(e=>{e.setAttribute('stroke',S.kit);e.setAttribute('fill',S.kit);});
  paintKitDark.forEach(e=>{e.setAttribute('stroke',kd);e.setAttribute('fill',kd);});
}
/* hour keyframes: h, skyTop, skyMid, horizon, seaFar, seaNear, cloud, sand, tint, tintAmt, stars */
const KEYS=[
[0,  '#050a1c','#0a1531','#17264a','#0b2036','#071426','#232f4e','#565273','#0a1030',.50,1],
[4.5,'#070f26','#101c3e','#2c2f5e','#0d2440','#08182e','#2a3355','#5d5678','#0a1030',.46,.95],
[6,  '#27407e','#7a5a8e','#ff9e6a','#1c4a66','#123048','#e8a58e','#caa27e','#3a2a5e',.22,.25],
[8,  '#2f7cc4','#7cc0e8','#ffe0ae','#1197b4','#0c6f92','#fff0da','#efd6a0','#ffb02e',.05,0],
[12, '#1f8fe0','#6fd0f5','#c9f0ff','#0fa8c9','#0b7fa6','#ffffff','#f4dfae','#ffffff',0,0],
[16.5,'#2b80d0','#7cc4ee','#ffe6b0','#0e9cb8','#0a7396','#fff3da','#f6dfa6','#ffb02e',.06,0],
[18.6,'#4a3f96','#ff8a5e','#ffc46b','#5e5fae','#39418a','#ffc2a0','#e6b48c','#ff5d4d',.16,.05],
[20, '#1d2254','#4a3a7e','#b06a8e','#25355e','#152242','#54507e','#8a7590','#1c1f4e',.36,.55],
[22, '#081026','#0e1a3a','#1f2c52','#0d2240','#081628','#2a3458','#5a5578','#0a1030',.48,.95],
[24, '#050a1c','#0a1531','#17264a','#0b2036','#071426','#232f4e','#565273','#0a1030',.50,1]];
function hourName(h){return h<5?'深夜':h<6.5?'黎明':h<11?'上午':h<14?'正午':
  h<17?'下午':h<18.7?'黄金时刻':h<20?'日落':h<21.5?'黄昏':'夜晚';}
function applyTime(){
  const h=S.hour; let a=KEYS[0],b=KEYS[KEYS.length-1];
  for(let i=0;i<KEYS.length-1;i++)if(h>=KEYS[i][0]&&h<=KEYS[i+1][0]){a=KEYS[i];b=KEYS[i+1];break;}
  const t=(h-a[0])/Math.max(.001,b[0]-a[0]);
  const C=i=>mixHex(a[i],b[i],t), N=i=>lerp(a[i],b[i],t);
  skyStops[0].setAttribute('stop-color',C(1));
  skyStops[1].setAttribute('stop-color',C(2));
  skyStops[2].setAttribute('stop-color',C(3));
  seaStops[0].setAttribute('stop-color',C(4));
  seaStops[1].setAttribute('stop-color',C(5));
  R.horizon.setAttribute('fill',C(3));
  R.waves.forEach(w=>w.el.setAttribute('fill',mixHex(C(5),'#eef9ff',w.mix)));
  clouds.forEach(c=>c.puffs.forEach(p=>p.setAttribute('fill',C(6))));
  R.sand.setAttribute('fill',C(7));
  R.tint.setAttribute('fill',C(8)); R.tint.setAttribute('opacity',f2(N(9)));
  night=N(10);
  R.starG.setAttribute('opacity',night>0.02?1:0);
  /* sun & moon */
  const ps=(h-5.7)/13.6;
  sunUp=(ps>0&&ps<1)?Math.sin(ps*Math.PI):0;
  sunX=lerp(-80,1280,clamp(ps,0,1)); sunY=470-sunUp*390;
  R.sunG.setAttribute('transform','translate('+f2(sunX)+','+f2(sunY)+')');
  R.sunG.setAttribute('opacity',f2(clamp(sunUp*5,0,1)));
  R.sunDisc.setAttribute('fill',mixHex('#ff9a3d','#fff4d6',clamp(sunUp*1.4,0,1)));
  const pm=((h+24-19.8)%24)/9.6;
  const mUp=(pm>0&&pm<1)?Math.sin(pm*Math.PI):0;
  moonX=lerp(-80,1280,clamp(pm,0,1)); moonY=470-mUp*380;
  R.moonG.setAttribute('transform','translate('+f2(moonX)+','+f2(moonY)+')');
  R.moonG.setAttribute('opacity',f2(clamp(mUp*5,0,1)*clamp(night*2,0,1)));
  R.moonShade.setAttribute('fill',C(1));
  const gx=night>.5?moonX:sunX;
  glitter.forEach(g=>{g.el.setAttribute('fill',night>.5?'#cfe8ff':'#ffd98a');
    g.el.setAttribute('x',f2(clamp(gx,60,1140)+g.dx));});
  R.glitBase=(1-night)*.5*clamp(sunUp*2,0,1)+night*.3;
  const hh=Math.floor(h)%24, mm=Math.round((h-Math.floor(h))*60);
  $('hourVal').textContent=String(hh).padStart(2,'0')+':'+String(mm).padStart(2,'0')+' · '+hourName(h);
}

/* ============================== body-space math ============================== */
let bobY=0, pitch=0;
function bodyToWorld(lx,ly){
  const c=Math.cos(pitch/DEG), s=Math.sin(pitch/DEG);
  return {x:D.H.x+lx*c-ly*s, y:D.H.y+bobY+lx*s+ly*c};
}
function solveIK(H,P){
  let dx=P.x-H.x, dy=P.y-H.y, d=Math.hypot(dx,dy);
  d=clamp(d,Math.abs(L1-L2)+1,L1+L2-1);
  const ux=dx/Math.hypot(dx,dy), uy=dy/Math.hypot(dx,dy);
  const a=(L1*L1-L2*L2+d*d)/(2*d), hh=Math.sqrt(Math.max(0,L1*L1-a*a));
  return {x:H.x+ux*a+uy*hh, y:H.y+uy*a-ux*hh};
}
