/* ============================== audio ============================== */
let AC=null, master=null, ambGain=null, audioReady=false;
function initAudio(){
  if(audioReady||!S.sound)return;
  try{
    const Ctx=window.AudioContext||window.webkitAudioContext; if(!Ctx)return;
    AC=new Ctx(); master=AC.createGain(); master.gain.value=.6; master.connect(AC.destination);
    /* surf ambience: looped noise -> lowpass -> slow swelling gain */
    const len=2*AC.sampleRate, buf=AC.createBuffer(1,len,AC.sampleRate), ch=buf.getChannelData(0);
    let l=0; for(let i=0;i<len;i++){l=l*.97+(Math.random()*2-1)*.03;ch[i]=l*6;}
    const src=AC.createBufferSource(); src.buffer=buf; src.loop=true;
    const lp=AC.createBiquadFilter(); lp.type='lowpass'; lp.frequency.value=340; lp.Q.value=.6;
    ambGain=AC.createGain(); ambGain.gain.value=.07;
    const lfo=AC.createOscillator(); lfo.frequency.value=.11;
    const lfoG=AC.createGain(); lfoG.gain.value=.045;
    lfo.connect(lfoG); lfoG.connect(ambGain.gain);
    src.connect(lp); lp.connect(ambGain); ambGain.connect(master);
    src.start(); lfo.start(); audioReady=true;
  }catch(e){}
}
function resumeAudio(){if(!AC)initAudio(); if(AC&&AC.state==='suspended'&&S.sound)AC.resume().catch(()=>{});}
function tickChain(vol){
  if(!audioReady||!S.sound||AC.state!=='running')return;
  try{const t=AC.currentTime, n=AC.createBufferSource(),
    b=AC.createBuffer(1,AC.sampleRate*.03,AC.sampleRate), d=b.getChannelData(0);
    for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*(1-i/d.length);
    n.buffer=b; const hp=AC.createBiquadFilter();hp.type='highpass';hp.frequency.value=1900;
    const g=AC.createGain();g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(.0001,t+.04);
    n.connect(hp);hp.connect(g);g.connect(master);n.start(t);n.stop(t+.05);}catch(e){}
}
function bellSound(){
  if(!audioReady||!S.sound)return; resumeAudio(); if(!AC)return;
  try{[0,.13].forEach(off=>{const t=AC.currentTime+off;
    [[1720,.11],[2280,.07],[3450,.035]].forEach(p=>{
      const o=AC.createOscillator();o.type='sine';o.frequency.value=p[0]*(1+(Math.random()-.5)*.006);
      const g=AC.createGain();g.gain.setValueAtTime(p[1],t);g.gain.exponentialRampToValueAtTime(.0001,t+.7);
      o.connect(g);g.connect(master);o.start(t);o.stop(t+.75);});});}catch(e){}
}
function honkSound(){
  if(!audioReady||!S.sound)return; resumeAudio(); if(!AC)return;
  try{const t=AC.currentTime,o=AC.createOscillator();o.type='sawtooth';
    o.frequency.setValueAtTime(240,t);o.frequency.exponentialRampToValueAtTime(165,t+.3);
    const bp=AC.createBiquadFilter();bp.type='bandpass';bp.frequency.value=520;bp.Q.value=1.6;
    const g=AC.createGain();g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.22,t+.03);
    g.gain.exponentialRampToValueAtTime(.0001,t+.34);
    o.connect(bp);bp.connect(g);g.connect(master);o.start(t);o.stop(t+.4);
    const o2=AC.createOscillator();o2.type='square';o2.frequency.value=118;
    const g2=AC.createGain();g2.gain.setValueAtTime(.05,t);g2.gain.exponentialRampToValueAtTime(.0001,t+.28);
    o2.connect(g2);g2.connect(master);o2.start(t);o2.stop(t+.3);}catch(e){}
}
