/* ============================== main loop ============================== */
let lastChainStep=0;
function frame(now){
  requestAnimationFrame(frame);
  if(!last)last=now;
  const dt=Math.min(.05,(now-last)/1000); last=now;
  tAmb+=dt*ambScale;
  /* eased cadence */
  rpmCur+=(S.rpm-rpmCur)*Math.min(1,dt*3);
  const effRpm=S.paused?0:rpmCur;
  const wc=effRpm/60*TAU;                    // crank rad/s
  const gear=D.ringR/D.cogR, ww=wc*gear;     // wheel rad/s
  const vpx=ww*D.R, vms=vpx*PXM, kmh=vms*3.6;
  if(!S.paused){
    theta+=wc*dt; dist+=vms*dt;
    wheelDeg+=ww*dt*DEG; chainOff-=wc*D.ringR*dt;
    const step=Math.floor(theta/Math.PI);
    if(step!==lastChainStep){lastChainStep=step;if(effRpm>4)tickChain(.02+effRpm*.0005);}
  }
  const scroll=dist/PXM;
  /* camera */
  const z=S.zoom/100;
  world.setAttribute('transform','translate(600,430) scale('+z+') translate(-600,-430)');
  /* parallax layers */
  const wrap=(g,f)=>g.setAttribute('transform','translate('+f2(-(scroll*f%1200))+',0)');
  wrap(duneG,.3); wrap(palmG,.62); wrap(railG,1); wrap(plankG,1); wrap(fgG,1.25);
  waveOff+=(14+S.wind*.35)*dt*ambScale;
  R.waves.forEach((w,i)=>w.el.setAttribute('transform','translate('+f2(-(waveOff*w.rate%120))+','+
    f2(Math.sin(tAmb*.7+i)*1.5)+')'));
  clouds.forEach(c=>{
    const x=((c.x0-tAmb*(4+S.wind*.14)-scroll*.05)%1600+1600)%1600-200;
    c.g.setAttribute('transform','translate('+f2(x)+','+f2(c.y+Math.sin(tAmb*.3+c.ph)*4)+') scale('+c.s+')');});
  gulls.forEach(g=>{
    const x=((g.base-tAmb*g.sp-scroll*.02)%1500+1500)%1500-150;
    const fl=4+Math.sin(tAmb*7+g.ph)*6;
    g.path.setAttribute('d','M-14 0 Q-7 '+f2(-fl)+' 0 0 Q7 '+f2(-fl)+' 14 0');
    g.g.setAttribute('transform','translate('+f2(x)+','+f2(g.y+Math.sin(tAmb*.9+g.ph)*7)+') scale('+g.sc+')');});
  boatX-= (8+S.wind*.06)*dt*ambScale; if(boatX<-160)boatX=1360;
  R.boatG.setAttribute('transform','translate('+f2(boatX)+','+f2(492+Math.sin(tAmb*.8)*3)+
    ') rotate('+f2(Math.sin(tAmb*.8+.5)*2.5)+')');
  R.boatLamp.setAttribute('opacity',f2(night*.9));
  palms.forEach(p=>p.fr.setAttribute('transform','translate('+p.x+','+p.y+') rotate('+
    f2(Math.sin(tAmb*.9+p.ph)*(2+S.wind*.05))+')'));
  glitter.forEach((g,i)=>g.el.setAttribute('opacity',
    f2(R.glitBase*(0.4+0.6*Math.abs(Math.sin(tAmb*2.4+g.ph))))));
  /* stars & shooting star */
  if(night>0.02){stars.forEach(s=>s.el.setAttribute('opacity',
    f2(clamp(night*1.6*(0.5+0.5*Math.sin(tAmb*s.sp+s.ph)),0,1))));
    if(tAmb>shootAt&&night>.5){shootP=0;shootAt=tAmb+12+Math.random()*14;
      shootX=200+Math.random()*800;shootY=30+Math.random()*130;}
  }
  if(shootP<1){shootP+=dt/.7;const p=clamp(shootP,0,1);
    const x=shootX-260*p,y=shootY+90*p;
    R.shoot.setAttribute('x1',f2(x));R.shoot.setAttribute('y1',f2(y));
    R.shoot.setAttribute('x2',f2(x+46));R.shoot.setAttribute('y2',f2(y-16));
