  const sag=Math.sin(theta*2+2)*3*(S.bounce/5+.3)+open*30;
  R.pouch.setAttribute('d','M129 -148 Q196 '+f2(-104+sag)+' 256 -142 Q261 -142 260 -146 L129 -153 Z');
  R.pouchG.setAttribute('transform','rotate('+f2(open*14)+' 129 -148)');
  R.upperBeakG.setAttribute('transform','rotate('+f2(-open*10)+' 126 -152)');
  R.fishPoke.setAttribute('opacity',fishT<1?0:1);
  /* scarf ribbon */
  const root=bodyToWorld(84,-116);
  const Nseg=Math.round(S.scarf), segLen=13;
  const amp=3+S.wind*.10+effRpm*.04, freq=3+effRpm*.05+S.wind*.06;
  const droop=Math.max(6,26*(1-S.wind*.008)), lift=S.wind*.35;
  function ribbon(n,phase,width){
    let d='M'+f2(root.x)+' '+f2(root.y),lx=root.x,ly=root.y;
    for(let i=1;i<=n;i++){const t=i/n;
      lx=root.x-i*segLen*(1-.15*t);
      ly=root.y+Math.sin(tAmb*freq-i*.7+phase)*amp*t+droop*Math.pow(t,1.6)-lift*i/Nseg;
      d+=' L'+f2(lx)+' '+f2(ly);}
    return {d,lx,ly};}
  const rm=ribbon(Nseg,0), rs=ribbon(Math.max(3,Math.round(Nseg*.65)),1.7);
  R.scarfMain.setAttribute('d',rm.d); R.scarfSub.setAttribute('d',rs.d);
  R.scarfKnot.setAttribute('cx',f2(root.x));R.scarfKnot.setAttribute('cy',f2(root.y));
  R.fringe.forEach((l,i)=>{setLine(l,{x:rm.lx,y:rm.ly},
    {x:rm.lx-9,y:rm.ly+(i-1)*6+Math.sin(tAmb*freq+i)*2});});
  /* bell ring animation */
  if(ringT<1){ringT+=dt/.9;const p=clamp(ringT,0,1);
    R.bellArcs.setAttribute('opacity',f2(1-p));
    R.bellArcs.setAttribute('transform','scale('+f2(1+p*1.7)+')');
    R.bellDome.setAttribute('transform','scale('+f2(1+.15*Math.sin(p*Math.PI*4)*(1-p))+')');
    const pop=p<.2?(p/.2)*(1.15-.15*(p/.2)):1;
    R.comicBell.setAttribute('x',f2(D.bell.x-6));
    R.comicBell.setAttribute('y',f2(D.bell.y-44-30*p));
    R.comicBell.setAttribute('opacity',f2(p<.7?1:1-(p-.7)/.3));
    R.comicBell.setAttribute('transform','rotate(-8 '+f2(D.bell.x-6)+' '+f2(D.bell.y-60)+
      ') translate('+f2(D.bell.x-6)+' '+f2(D.bell.y-60)+') scale('+f2(pop)+') translate('+f2(-(D.bell.x-6))+' '+f2(-(D.bell.y-60))+')');
  } else {R.bellArcs.setAttribute('opacity',0);R.bellDome.setAttribute('transform','');
    R.comicBell.setAttribute('opacity',0);}
  /* honk comic */
  if(honkT<1){const p=clamp(honkT,0,1),pop=p<.2?(p/.2)*1.1:1.1-.1*Math.min(1,(p-.2)/.3);
    R.comicHonk.setAttribute('opacity',f2(p<.65?1:1-(p-.65)/.35));
    const hx=+R.comicHonk.getAttribute('x'),hy=+R.comicHonk.getAttribute('y');
    R.comicHonk.setAttribute('transform','rotate(6 '+hx+' '+hy+') translate('+hx+' '+f2(hy-20*p)+
      ') scale('+f2(pop)+') translate('+(-hx)+' '+(-hy)+')');}
  else R.comicHonk.setAttribute('opacity',0);
  /* fish jump */
  if(fishT<1){fishT+=dt/1.0;const p=clamp(fishT,0,1);
    const fx=fishStart.x+Math.sin(p*Math.PI)*60, fy=fishStart.y-160*Math.sin(p*Math.PI);
    R.fishJumpG.setAttribute('opacity',f2(p<.9?1:1-(p-.9)/.1));
    R.fishJumpG.setAttribute('transform','translate('+f2(fx)+','+f2(fy)+') rotate('+f2(p*300-20)+')');
    R.sparkles.forEach((s,i)=>{const sp=clamp((p-.3-i*.08)*3,0,1);
      s.setAttribute('cx',f2(fishStart.x+30+i*16));s.setAttribute('cy',f2(fishStart.y-140+i*10));
      s.setAttribute('opacity',f2(Math.sin(sp*Math.PI)*.9));});}
  else {R.fishJumpG.setAttribute('opacity',0);R.sparkles.forEach(s=>s.setAttribute('opacity',0));}
  /* speed lines & dust */
  const slOp=S.spray?clamp((kmh-20)/40,0,1)*.35:0;
  speedRects.forEach(s=>{
    s.el.setAttribute('x',f2(1250-((scroll*2.2+s.off)%1500)));
    s.el.setAttribute('width',f2(40+kmh*3));
    s.el.setAttribute('opacity',f2(slOp));});
  if(S.spray&&!S.paused&&effRpm>15){
    spawnAcc+=dt*(effRpm/12);
    while(spawnAcc>1){spawnAcc-=1;
      const d=dust.find(q=>!q.on); if(!d)break;
      d.on=true;d.age=0;d.life=.5+Math.random()*.4;
      d.x=D.A.x-6;d.y=GY-2;d.r=2+Math.random()*3;
      d.vx=-(60+vpx*.3)+(Math.random()-.5)*30;d.vy=-20-Math.random()*45;
      d.el.setAttribute('display','inline');d.el.setAttribute('r',f2(d.r));}
  }
  dust.forEach(d=>{if(!d.on)return;d.age+=dt;
    if(d.age>=d.life){d.on=false;d.el.setAttribute('display','none');return;}
    d.x+=d.vx*dt;d.y+=d.vy*dt;d.vy+=140*dt;
    d.el.setAttribute('cx',f2(d.x));d.el.setAttribute('cy',f2(d.y));
    d.el.setAttribute('opacity',f2(.7*(1-d.age/d.life)));});
  /* guides */
  if(S.guides){
    setLine(R.gBones[0],hn,kn);setLine(R.gBones[1],kn,pn);
    setLine(R.gBones[2],hf,kf);setLine(R.gBones[3],kf,pf);
    [hn,kn,pn,hf,kf,pf].forEach((j,i)=>{R.gJoints[i].setAttribute('cx',f2(j.x));
      R.gJoints[i].setAttribute('cy',f2(j.y));});
    R.gTheta.textContent='θ '+Math.round((theta*DEG)%360)+'°';
    R.gCad.textContent='踏频 '+Math.round(effRpm)+' 转/分';
  }
  /* HUD */
  hudT+=dt;
  if(hudT>.2){hudT=0;
    $('hudSpeed').textContent=kmh.toFixed(1);
    $('hudCad').textContent=Math.round(effRpm);
    $('hudTrip').textContent=dist<1000?Math.round(dist)+' 米':(dist/1000).toFixed(2)+' 公里';}
}

/* ============================== boot ============================== */
rebuild(); applyPaint(); applyTime(); refreshControls();
setSound(true); setPaused(false);
if(reduced){setPaused(true);toast('检测到系统开启了“减少动效”，准备好后按空格键开始','var(--amber)');}
setTimeout(()=>$('bellHint').classList.add('hide'),20000);
requestAnimationFrame(frame);
})();
</script>
</body>
</html>
